import { useState, useEffect, useCallback, useMemo, useRef, memo } from 'react';
import { scopedStorage } from '@lark-apaas/client-toolkit-lite';
import { Card, CardHeader, CardContent, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Textarea } from '@/components/ui/textarea';
import { Badge } from '@/components/ui/badge';
import { ScrollArea } from '@/components/ui/scroll-area';
import { Trash2, Plus, Check, Tag, X, ChevronDown, MapPin, ChevronUp } from 'lucide-react';
import { cn, ensureArray } from '@/lib/utils';
import { format } from 'date-fns';
import { zhCN } from 'date-fns/locale';
import { NOTE_TAG_PRESETS } from '@/data/note-tags';

export interface NoteItem {
  id: string;
  content: string;
  date: string;
  source: '我的笔记';
  tags: string[];
  /** 美食笔记专用：地址字段 */
  address?: string;
}

interface NotePadSectionProps {
  storageKey: string;
  title: string;
  icon?: React.ReactNode;
  theme: {
    primary: string;
    ui: {
      cardBg?: string;
      cardBorder?: string;
      glassBg?: string;
      badgeBg?: string;
    };
  };
  placeholder?: string;
  className?: string;
  /** 外部笔记数组（可选，用于搜索结果展示；不传则用内部 state） */
  notes?: NoteItem[];
  /** 笔记变化回调，用于父级同步到搜索数据源 */
  onNotesChange?: (notes: NoteItem[]) => void;
  /** 是否展示为搜索结果样式（隐藏输入框） */
  searchMode?: boolean;
}

function NotePadSection({
  storageKey,
  title,
  icon,
  theme,
  placeholder = '记录你的个人技巧和心得...',
  className,
  notes: externalNotes,
  onNotesChange,
  searchMode = false,
}: NotePadSectionProps) {
  const [internalNotes, setInternalNotes] = useState<NoteItem[]>([]);
  const [input, setInput] = useState('');
  const [addressInput, setAddressInput] = useState('');
  const [cityInput, setCityInput] = useState('');
  const [saved, setSaved] = useState(false);
  const [selectedTags, setSelectedTags] = useState<string[]>([]);
  const [tagPickerOpen, setTagPickerOpen] = useState(false);
  const [expanded, setExpanded] = useState(false);
  const savedTimerRef = useRef<number | null>(null);

  const tagPresets = NOTE_TAG_PRESETS[storageKey] || [];
  const isFoodNote = storageKey === 'note:food';
  const notes = externalNotes ?? internalNotes;

  // 初始加载
   useEffect(() => {
     if (externalNotes) return;
     try {
       const raw = scopedStorage.getItem(storageKey);
       if (raw) {
         const parsed = JSON.parse(raw);
         if (Array.isArray(parsed)) setInternalNotes(parsed);
       }
     } catch {
       // noop
     }
     // 卸载时清理定时器
     return () => {
       if (savedTimerRef.current) {
         clearTimeout(savedTimerRef.current);
         savedTimerRef.current = null;
       }
     };
   }, [storageKey, externalNotes]);

  // 保存到 localStorage 并通知父级
  const persist = useCallback(
    (list: NoteItem[]) => {
      try {
        scopedStorage.setItem(storageKey, JSON.stringify(list));
      } catch {
        // noop
      }
      onNotesChange?.(list);
    },
    [storageKey, onNotesChange]
  );

  const toggleTag = (tag: string) => {
    setSelectedTags(prev =>
      prev.includes(tag) ? prev.filter(t => t !== tag) : [...prev, tag]
    );
  };

  const addNote = () => {
    const text = input.trim();
    if (!text) return;
    const newNote: NoteItem = {
      id: `note-${Date.now()}-${Math.random().toString(36).slice(2, 6)}`,
      content: text,
      date: format(new Date(), 'yyyy-MM-dd', { locale: zhCN }),
      source: '我的笔记',
      tags: [...selectedTags],
      address: isFoodNote && addressInput.trim() ? addressInput.trim() : undefined,
    };
    const next = [newNote, ...internalNotes];
    setInternalNotes(next);
    persist(next);
    setInput('');
    setAddressInput('');
    setCityInput('');
    setSelectedTags([]);
    setTagPickerOpen(false);
    setSaved(true);
    if (savedTimerRef.current) clearTimeout(savedTimerRef.current);
    savedTimerRef.current = setTimeout(() => setSaved(false), 1500) as unknown as number;
  };

  const deleteNote = (id: string) => {
    const next = internalNotes.filter(n => n.id !== id);
    setInternalNotes(next);
    persist(next);
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    if (e.key === 'Enter' && (e.metaKey || e.ctrlKey)) {
      e.preventDefault();
      addNote();
    }
  };

  const sortedNotes = useMemo(
    () => [...notes].sort((a, b) => b.date.localeCompare(a.date)),
    [notes]
  );

  const COLLAPSED_LIMIT = 3;
  const needsCollapse = sortedNotes.length > COLLAPSED_LIMIT;
  const visibleCount = expanded || !needsCollapse ? sortedNotes.length : COLLAPSED_LIMIT;
  const visibleNotes = sortedNotes.slice(0, visibleCount);
  const hiddenCount = sortedNotes.length - COLLAPSED_LIMIT;

  return (
    <Card
      className={cn(
        'search-focus-glow border transition-all duration-300',
        className
      )}
      style={{
        backgroundColor: theme.ui.glassBg || 'rgba(255,255,255,0.6)',
        backdropFilter: 'blur(10px)',
        WebkitBackdropFilter: 'blur(10px)',
        borderColor: theme.ui.cardBorder,
      }}
    >
      <CardHeader className="pb-2">
        <div className="flex items-center gap-2">
          {icon && (
            <div
              className="flex size-8 shrink-0 items-center justify-center rounded-lg"
              style={{
                backgroundColor: theme.ui.badgeBg || `${theme.primary}15`,
                color: theme.primary,
              }}
            >
              {icon}
            </div>
          )}
          <div className="flex-1">
            <CardTitle className="text-base">{title}</CardTitle>
          </div>
          <Badge
            className="text-xs border-0"
            style={{
              backgroundColor: theme.ui.badgeBg || `${theme.primary}15`,
              color: theme.primary,
            }}
          >
            {sortedNotes.length}条
          </Badge>
        </div>
        {/* 主题色分割线 */}
        <div
          className="mt-2 h-px w-full"
          style={{
            background: `linear-gradient(90deg, ${theme.primary}40, transparent)`,
          }}
        />
      </CardHeader>
      <CardContent className="space-y-3">
        {/* 输入区（搜索模式下隐藏） */}
        {!searchMode && (
          <div className="space-y-2">
            <Textarea
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={handleKeyDown}
              placeholder={placeholder}
              className="min-h-[90px] text-sm resize-y leading-relaxed"
              style={{
                backgroundColor: theme.ui.cardBg || 'rgba(255,255,255,0.5)',
                borderColor: theme.ui.cardBorder,
              }}
            />

            {/* 美食笔记：地址输入 + 自定义城市 */}
            {isFoodNote && (
              <div className="space-y-2">
                <div className="flex items-center gap-2 rounded-md border px-3 py-2 backdrop-blur-sm transition-colors focus-within:ring-1 focus-within:ring-ring/50"
                  style={{
                    backgroundColor: theme.ui.cardBg || 'rgba(255,255,255,0.5)',
                    borderColor: theme.ui.cardBorder || 'hsl(var(--border))',
                  }}
                >
                  <MapPin className="size-3.5 text-muted-foreground shrink-0" />
                  <input
                    type="text"
                    value={addressInput}
                    onChange={(e) => setAddressInput(e.target.value)}
                    placeholder="输入具体地址（可选）"
                    className="flex-1 text-xs bg-transparent outline-none placeholder:text-muted-foreground"
                  />
                </div>
                <div className="flex items-center gap-2 rounded-md border px-3 py-2 backdrop-blur-sm transition-colors focus-within:ring-1 focus-within:ring-ring/50"
                  style={{
                    backgroundColor: theme.ui.cardBg || 'rgba(255,255,255,0.5)',
                    borderColor: theme.ui.cardBorder || 'hsl(var(--border))',
                  }}
                >
                  <span className="size-3.5 shrink-0 flex items-center justify-center text-muted-foreground">🏙️</span>
                  <input
                    type="text"
                    value={cityInput}
                    onChange={(e) => setCityInput(e.target.value)}
                    placeholder="其他城市手动输入"
                    className="flex-1 text-xs bg-transparent outline-none placeholder:text-muted-foreground"
                  />
                  {cityInput.trim() && (
                    <button
                      type="button"
                      onClick={() => {
                        const val = cityInput.trim();
                        if (val && !selectedTags.includes(val)) {
                          setSelectedTags(prev => [...prev, val]);
                        }
                        setCityInput('');
                      }}
                      className="text-[10px] px-2 py-0.5 rounded-full text-white"
                      style={{ backgroundColor: theme.primary }}
                    >
                      添加
                    </button>
                  )}
                </div>
              </div>
            )}

            {/* 标签选择区 */}
            {tagPresets.length > 0 && (
              <div>
                <button
                  type="button"
                  onClick={() => setTagPickerOpen(v => !v)}
                  className="flex items-center gap-1.5 text-xs text-muted-foreground hover:text-foreground transition-colors"
                >
                  <Tag className="size-3" />
                  <span>标签</span>
                  {selectedTags.length > 0 && (
                    <Badge
                      className="text-[10px] border-0"
                      style={{ backgroundColor: `${theme.primary}15`, color: theme.primary }}
                    >
                      已选{selectedTags.length}
                    </Badge>
                  )}
                  <ChevronDown
                    className={cn(
                      'size-3 transition-transform',
                      tagPickerOpen && 'rotate-180'
                    )}
                  />
                </button>
                {tagPickerOpen && (
                  <div className="mt-2 flex flex-wrap gap-1.5 p-2 rounded-md bg-muted/40 border border-border/40">
                    {tagPresets.map(tag => {
                      const active = selectedTags.includes(tag);
                      return (
                        <button
                          key={tag}
                          type="button"
                          onClick={() => toggleTag(tag)}
                          className={cn(
                            'px-2 py-1 text-[11px] rounded-full transition-all border',
                            active
                              ? 'text-white border-transparent'
                              : 'bg-background text-muted-foreground border-border/60 hover:border-border'
                          )}
                          style={active ? { backgroundColor: theme.primary } : {}}
                        >
                          {active && <Check className="inline size-3 mr-0.5 -translate-y-px" />}
                          {tag}
                        </button>
                      );
                    })}
                  </div>
                )}
              </div>
            )}

            <div className="flex items-center justify-between">
              <span className="text-[10px] text-muted-foreground">
                支持多行 · Ctrl/Cmd + Enter 快速保存
              </span>
              <Button
                size="sm"
                style={{ backgroundColor: theme.primary, color: '#fff' }}
                onClick={addNote}
                className="backdrop-blur-sm"
              >
                {saved ? (
                  <><Check className="size-3.5 mr-1" />已保存</>
                ) : (
                  <><Plus className="size-3.5 mr-1" />保存笔记</>
                )}
              </Button>
            </div>
          </div>
        )}

        {/* 笔记列表 */}
        {sortedNotes.length === 0 ? (
          <div className="text-center py-6 text-muted-foreground text-sm">
            还没有笔记，写下第一条吧～
          </div>
        ) : (
          <ScrollArea className={searchMode ? '' : 'max-h-[420px]'}>
            <div className="space-y-2 pr-1">
                {visibleNotes.map((note) => (
                  <div
                    key={note.id}
                    className="relative overflow-hidden transition-all duration-300"
                  >
                    <div className="relative p-3 rounded-lg bg-muted/30 border border-border/40 group hover:bg-muted/50 transition-colors">
                      {!searchMode && (
                        <Button
                          size="icon"
                          variant="ghost"
                          className="!absolute -top-2 -right-2 z-20 h-7 w-7 rounded-full bg-background/80 backdrop-blur-sm opacity-0 group-hover:opacity-100 transition-opacity shadow-sm"
                          onClick={() => deleteNote(note.id)}
                          aria-label="删除笔记"
                        >
                          <Trash2 className="h-3.5 w-3.5 text-muted-foreground hover:text-destructive" />
                        </Button>
                      )}
                      <div className="flex flex-wrap items-center gap-1.5 mb-1.5">
                        <Badge
                          className="text-[10px] border-0"
                          style={{
                            backgroundColor: `${theme.primary}15`,
                            color: theme.primary,
                          }}
                        >
                          {note.source}
                        </Badge>
                        {ensureArray(note.tags).length > 0 && ensureArray(note.tags).map(tag => (
                          <Badge
                            key={tag}
                            variant="outline"
                            className="text-[10px] font-normal"
                          >
                            {tag}
                          </Badge>
                        ))}
                        <span className="text-[10px] text-muted-foreground ml-auto">
                          {note.date}
                        </span>
                      </div>
                      <p className="text-sm whitespace-pre-wrap leading-relaxed text-foreground">
                        {note.content}
                      </p>
                      {note.address && (
                        <div className="mt-1.5 flex items-center gap-1 text-[11px] text-muted-foreground">
                          <MapPin className="size-3" />
                          <span>{note.address}</span>
                        </div>
                      )}
                    </div>
                  </div>
                ))}
              </div>
          </ScrollArea>
        )}

        {/* 展开 / 收起按钮 */}
        {needsCollapse && !searchMode && (
          <button
            type="button"
            onClick={() => setExpanded(v => !v)}
            className="mt-3 w-full flex items-center justify-center gap-1 py-2 text-xs text-muted-foreground hover:text-foreground rounded-md hover:bg-muted/50 transition-colors"
          >
            {expanded ? (
              <>
                <ChevronUp className="size-3.5" />
                收起
              </>
            ) : (
              <>
                <ChevronDown className="size-3.5" />
                展开全部 {sortedNotes.length} 条
              </>
            )}
          </button>
        )}
      </CardContent>
    </Card>
  );
}

export default memo(NotePadSection);
